<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../Layouts/AdminLayout.vue';
const props = defineProps({ settings: Object });
const form = useForm({ phone: props.settings.phone || '', whatsapp: props.settings.whatsapp || '', logo: null, favicon: null });
const save = () => form.post('/admin/settings', { forceFormData: true });
</script>
<template><Head title="Settings" /><AdminLayout><div class="page-heading"><div><p class="eyebrow">Business details</p><h1>Settings</h1><p>Manage the contact details and brand assets used on the public website.</p></div></div><form class="content-card settings-form" @submit.prevent="save"><div><p class="eyebrow">Contact details</p><h2>Phone & WhatsApp</h2><p>Use country codes, for example: +880 1712 345678. WhatsApp opens directly from the floating website button.</p></div><label>Phone number<input v-model="form.phone" type="tel" placeholder="+880 1712 345678"><small v-if="form.errors.phone">{{ form.errors.phone }}</small></label><label>WhatsApp number<input v-model="form.whatsapp" type="tel" placeholder="+880 1712 345678"><small v-if="form.errors.whatsapp">{{ form.errors.whatsapp }}</small></label><div class="settings-assets"><div><p class="eyebrow">Branding</p><h2>Logo & favicon</h2><p>Logo: PNG, JPG, or WebP, maximum 2 MB. Favicon: ICO, PNG, JPG, or WebP, maximum 1 MB.</p></div><label>Website logo<input type="file" accept="image/png,image/jpeg,image/webp" @input="form.logo = $event.target.files[0]"><img v-if="settings.logo_url" :src="settings.logo_url" alt="Current logo" class="asset-preview"><small v-if="form.errors.logo">{{ form.errors.logo }}</small></label><label>Browser favicon<input type="file" accept=".ico,image/png,image/jpeg,image/webp" @input="form.favicon = $event.target.files[0]"><img v-if="settings.favicon_url" :src="settings.favicon_url" alt="Current favicon" class="favicon-preview"><small v-if="form.errors.favicon">{{ form.errors.favicon }}</small></label></div><button class="button primary" :disabled="form.processing">{{ form.processing ? 'Saving…' : 'Save settings' }} <span>→</span></button></form></AdminLayout></template>
